-- 0102's Net Worth value for collector pieces, except reward pieces (the pass and the pack): they stay at 0, so real money
-- never moves Net Worth or rank.
create or replace function public.collector_tab_value() returns trigger
language plpgsql security definer set search_path = public
as $$
declare
  v_tab text;
  v_reward boolean;
begin
  if new.acquired = 'collector' then
    select tab, coalesce((city ->> 'reward')::boolean, false) into v_tab, v_reward from public.shop_catalog where sku = new.sku;
    if v_reward then new.value := 0;
    elsif v_tab is not null then new.value := coalesce(public.collector_value(v_tab), new.value); end if;
  end if;
  return new;
end;
$$;

-- ---------------------------------------------------------------------------
-- VIP includes the Clout Pass
-- ---------------------------------------------------------------------------
create or replace function public.has_entitlement(p_player uuid, p_sku text) returns boolean
language sql stable security definer set search_path = public
as $$
  select exists (select 1 from public.entitlements where player_id = p_player and sku = p_sku and status = 'active')
      or (exists (select 1 from public.store_products where sku = p_sku and product_type in ('side_arc', 'season_pass'))
          and public.vip_member(p_player))
$$;

-- ---------------------------------------------------------------------------
-- Season XP
-- ---------------------------------------------------------------------------
create table if not exists public.season_xp (
  player_id  uuid not null references public.players (id) on delete cascade,
  season     text not null,
  kind       text not null,
  ref        text not null,
  xp         int not null check (xp > 0),
  ny_date    date not null,
  created_at timestamptz not null default now(),
  primary key (player_id, season, kind, ref)
);
create index if not exists season_xp_day_idx on public.season_xp (player_id, season, ny_date);
alter table public.season_xp enable row level security;

create table if not exists public.season_claims (
  player_id  uuid not null references public.players (id) on delete cascade,
  season     text not null,
  tier       int not null,
  track      text not null check (track in ('free', 'paid')),
  created_at timestamptz not null default now(),
  primary key (player_id, season, tier, track)
);
alter table public.season_claims enable row level security;

/** The season row of game_settings, or null. */
create or replace function public.season_settings() returns jsonb
language sql stable security definer set search_path = public
as $$ select public.game_settings_value('season_pass') $$;

/** Ledger trigger: a listed kind earns XP while a season runs (once per kind and ref). Never raises. */
create or replace function public.season_xp_note() returns trigger
language plpgsql security definer set search_path = public
as $$
declare
  s jsonb;
  pts int;
  today date;
begin
  begin
    s := public.season_settings();
    if s is null then return new; end if;
    pts := (s -> 'xp' ->> new.kind)::int;
    if pts is null or pts <= 0 then return new; end if;
    today := public.ny_today();
    if today < (s ->> 'starts')::date or today > (s ->> 'ends')::date then return new; end if;
    insert into public.season_xp (player_id, season, kind, ref, xp, ny_date)
    values (new.player_id, s ->> 'id', new.kind, new.ref, pts, today)
    on conflict do nothing;
  exception when others then
    raise warning 'season_xp_note: %', sqlerrm;
  end;
  return new;
end;
$$;
drop trigger if exists ledger_season_xp on public.ledger;
create trigger ledger_season_xp after insert on public.ledger
  for each row execute function public.season_xp_note();

/** The player's season: XP, phase, the paid row and what's claimed (lib/seasonPass.ts PassState). */
create or replace function public.season_state() returns jsonb
language plpgsql stable security definer set search_path = public
as $$
declare
  uid uuid := auth.uid();
  s jsonb := public.season_settings();
  today date := public.ny_today();
  v_phase text;
begin
  if uid is null or s is null then return null; end if;
  v_phase := case when today < (s ->> 'starts')::date then 'soon'
                  when today <= (s ->> 'ends')::date then 'on'
                  when today <= (s ->> 'ends')::date + (s ->> 'claimDays')::int then 'claim'
                  else 'over' end;
  return jsonb_build_object(
    'seasonId', s ->> 'id',
    'xp', coalesce((select sum(xp) from public.season_xp where player_id = uid and season = s ->> 'id'), 0),
    'today', coalesce((select sum(xp) from public.season_xp where player_id = uid and season = s ->> 'id' and ny_date = today), 0),
    'paid', public.has_entitlement(uid, s ->> 'sku'),
    'vip', public.vip_member(uid),
    'phase', v_phase,
    'pending', exists (select 1 from public.purchases u where u.player_id = uid and u.sku = s ->> 'sku' and u.status = 'pending'
                         and u.created_at > now() - interval '1 hour'),
    'claimed', jsonb_build_object(
      'free', coalesce((select jsonb_agg(tier order by tier) from public.season_claims where player_id = uid and season = s ->> 'id' and track = 'free'), '[]'::jsonb),
      'paid', coalesce((select jsonb_agg(tier order by tier) from public.season_claims where player_id = uid and season = s ->> 'id' and track = 'paid'), '[]'::jsonb)));
end;
$$;

/** Gives one reward (a piece arrives acquired 'collector', value 0). */
create or replace function public.season_give(p_player uuid, p_reward jsonb, p_ref text, p_paid boolean) returns void
language plpgsql security definer set search_path = public
as $$
declare
  k text := p_reward ->> 'kind';
  amt int := (p_reward ->> 'amount')::int;
begin
  if k = 'cash' and not p_paid then
    if public.ledger_once(p_player, 'cash', amt, 'season_free', p_ref) then
      update public.players set bank_cash = bank_cash + amt where id = p_player;
    end if;
  elsif k = 'clout' and not p_paid then
    if public.ledger_once(p_player, 'clout', amt, 'season_free', p_ref) then
      update public.players set clout = clout + amt where id = p_player;
    end if;
  elsif k = 'item' then
    insert into public.player_items (player_id, sku, category, value, acquired)
    values (p_player, p_reward ->> 'sku', coalesce(public.shop_item(p_reward ->> 'sku') ->> 'category', 'home'), 0, 'collector')
    on conflict (player_id, sku) do nothing;
  elsif k = 'badge' then
    insert into public.player_badges (player_id, badge_id, arc_id) values (p_player, p_reward ->> 'id', 'season')
    on conflict do nothing;
  end if;
end;
$$;

/** Claims every reward reached in both rows (the paid row only when open). Returns season_state() plus what came. */
create or replace function public.season_claim_all() returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  uid uuid := auth.uid();
  s jsonb := public.season_settings();
  st jsonb;
  reached int;
  t jsonb;
  r jsonb;
  got jsonb := '[]'::jsonb;
  open boolean;
  n int;
begin
  if uid is null or s is null then raise exception 'no_player' using errcode = '28000'; end if;
  if not exists (select 1 from public.players where id = uid and home_id is not null) then raise exception 'no_player' using errcode = '28000'; end if;
  perform 1 from public.players where id = uid for update;
  st := public.season_state();
  if st ->> 'phase' = 'soon' then raise exception 'season_soon' using errcode = '22023'; end if;
  if st ->> 'phase' = 'over' then raise exception 'season_over' using errcode = '22023'; end if;
  reached := least(jsonb_array_length(s -> 'tiers'), ((st ->> 'xp')::int / (s ->> 'xpPerTier')::int));
  open := (st ->> 'paid')::boolean;
  for t in select x from jsonb_array_elements(s -> 'tiers') x where (x ->> 'tier')::int <= reached order by (x ->> 'tier')::int loop
    insert into public.season_claims (player_id, season, tier, track) values (uid, s ->> 'id', (t ->> 'tier')::int, 'free')
    on conflict do nothing;
    get diagnostics n = row_count;
    if n > 0 then
      for r in select x from jsonb_array_elements(t -> 'free') x loop
        perform public.season_give(uid, r, (s ->> 'id') || ':' || (t ->> 'tier'), false);
        got := got || jsonb_build_array(r);
      end loop;
    end if;
    if open then
      insert into public.season_claims (player_id, season, tier, track) values (uid, s ->> 'id', (t ->> 'tier')::int, 'paid')
      on conflict do nothing;
      get diagnostics n = row_count;
      if n > 0 then
        for r in select x from jsonb_array_elements(t -> 'paid') x loop
          perform public.season_give(uid, r, (s ->> 'id') || ':' || (t ->> 'tier'), true);
          got := got || jsonb_build_array(r);
        end loop;
      end if;
    end if;
  end loop;
  return public.season_state() || jsonb_build_object('got', got);
end;
$$;

-- ---------------------------------------------------------------------------
-- The starter pack
-- ---------------------------------------------------------------------------
create or replace function public.starter_pack_state() returns jsonb
language sql stable security definer set search_path = public
as $$
  select case when p.id is null then null else jsonb_build_object(
    'owned', public.has_entitlement(p.id, c ->> 'sku'),
    'offer', not public.has_entitlement(p.id, c ->> 'sku') and p.created_at > now() - make_interval(days => (c ->> 'days')::int)
             and exists (select 1 from public.store_products sp where sp.sku = c ->> 'sku' and sp.active),
    'endsAt', p.created_at + make_interval(days => (c ->> 'days')::int),
    'pending', exists (select 1 from public.purchases u where u.player_id = p.id and u.sku = c ->> 'sku' and u.status = 'pending'
                         and u.created_at > now() - interval '1 hour')) end
  from (select public.game_settings_value('starter_pack') c) cfg
  left join public.players p on p.id = auth.uid() and p.home_id is not null;
$$;

/** The pack's pieces and badge arrive with its entitlement; a refund takes them back. A refunded pass takes back its paid row. */
create or replace function public.entitlements_season_items() returns trigger
language plpgsql security definer set search_path = public
as $$
declare
  c jsonb;
  s jsonb;
  v_sku text;
  t jsonb;
  r jsonb;
begin
  if new.product_type = 'bundle' then
    c := public.game_settings_value('starter_pack');
    if c is null or c ->> 'sku' <> new.sku then return new; end if;
    if new.status = 'active' then
      for v_sku in select jsonb_array_elements_text(c -> 'items') loop
        perform public.season_give(new.player_id, jsonb_build_object('kind', 'item', 'sku', v_sku), 'pack', true);
      end loop;
      perform public.season_give(new.player_id, jsonb_build_object('kind', 'badge', 'id', c ->> 'badge'), 'pack', true);
    elsif new.status = 'revoked' then
      delete from public.player_items i where i.player_id = new.player_id and i.acquired = 'collector'
         and i.sku in (select jsonb_array_elements_text(c -> 'items'));
      delete from public.player_badges where player_id = new.player_id and badge_id = c ->> 'badge';
    end if;
  elsif new.product_type = 'season_pass' and new.status = 'revoked' and not public.vip_member(new.player_id) then
    s := public.season_settings();
    if s is null or s ->> 'sku' <> new.sku then return new; end if;
    for t in select x from jsonb_array_elements(s -> 'tiers') x loop
      for r in select x from jsonb_array_elements(t -> 'paid') x loop
        if r ->> 'kind' = 'item' then
          delete from public.player_items i where i.player_id = new.player_id and i.sku = r ->> 'sku' and i.acquired = 'collector';
        elsif r ->> 'kind' = 'badge' then
          delete from public.player_badges where player_id = new.player_id and badge_id = r ->> 'id';
        end if;
      end loop;
    end loop;
    delete from public.season_claims where player_id = new.player_id and season = s ->> 'id' and track = 'paid';
  end if;
  return new;
end;
$$;
drop trigger if exists entitlements_season_items on public.entitlements;
create trigger entitlements_season_items after insert or update of status on public.entitlements
  for each row execute function public.entitlements_season_items();

-- ---------------------------------------------------------------------------
-- Checkout: 0134's start_purchase, plus the season's dates and the pack's window
-- ---------------------------------------------------------------------------
create or replace function public.start_purchase(p_sku text, p_session text)
returns text[]
language plpgsql security definer set search_path = public
as $$
declare
  uid uuid := auth.uid();
  prod public.store_products;
  cat public.shop_catalog;
  replaced text[];
  s jsonb;
  c jsonb;
begin
  select * into prod from public.store_products where sku = p_sku and active;
  if prod.sku is null then raise exception 'unknown_product' using errcode = '22023'; end if;
  if not exists (select 1 from public.players where id = uid and home_id is not null) then raise exception 'no_player' using errcode = '28000'; end if;
  -- VIP already includes the Clout Pass.
  if prod.product_type = 'season_pass' and public.vip_member(uid) then raise exception 'vip_has_pass' using errcode = '22023'; end if;
  if public.has_entitlement(uid, p_sku) then raise exception 'already_owned' using errcode = '22023'; end if;
  -- One pass is enough: no monthly plan on top of forever, or the other way round.
  if prod.product_type = 'chat_pass' and public.chat_unlimited(uid) then raise exception 'already_owned' using errcode = '22023'; end if;
  if p_session !~ '^(cs_[A-Za-z0-9_]+|steam:[0-9]{1,19})$' then raise exception 'bad_session' using errcode = '22023'; end if;
  if prod.product_type = 'postcard' and not exists (select 1 from public.place_visits where player_id = uid and place_id = prod.place_id) then
    raise exception 'visit_first' using errcode = '22023';
  end if;
  if prod.product_type = 'exclusive_event' and exists (select 1 from public.exclusive_events where sku = p_sku and ends_at <= public.game_now()) then
    raise exception 'event_over' using errcode = '22023';
  end if;
  -- 0156: the Clout Pass sells while its season runs; the starter pack in a player's first days.
  if prod.product_type = 'season_pass' then
    s := public.season_settings();
    if s is null or s ->> 'sku' <> p_sku then raise exception 'season_over' using errcode = '22023'; end if;
    if public.ny_today() < (s ->> 'starts')::date then raise exception 'season_soon' using errcode = '22023'; end if;
    if public.ny_today() > (s ->> 'ends')::date then raise exception 'season_over' using errcode = '22023'; end if;
  end if;
  if prod.product_type = 'bundle' then
    c := public.game_settings_value('starter_pack');
    if c is null or c ->> 'sku' <> p_sku
       or not exists (select 1 from public.players where id = uid and created_at > now() - make_interval(days => (c ->> 'days')::int)) then
      raise exception 'offer_over' using errcode = '22023';
    end if;
  end if;
  -- The player's row lock makes two checkouts at once wait for each other.
  perform 1 from public.players where id = uid for update;
  -- Catalog pieces (0102): on sale, and a numbered drop with a number left. The row lock makes two last-copy checkouts
  -- wait for each other. A player who was refunded keeps their number, so their checkout takes none.
  if prod.product_type = 'collector_item' then
    select * into cat from public.shop_catalog where sku = p_sku for update;
    if cat.sku is not null then
      if not public.shop_on_sale(p_sku) or not cat.wearable then raise exception 'not_for_sale' using errcode = '22023'; end if;
      if cat.tab = 'cars' and exists (select 1 from public.players where id = uid and car_mode = 'owned') then
        raise exception 'already_own_car' using errcode = '22023';
      end if;
      if cat.edition_size is not null
         and not exists (select 1 from public.entitlements where player_id = uid and sku = p_sku)
         and not exists (select 1 from public.purchases u where u.player_id = uid and u.sku = p_sku and u.status = 'pending'
                          and u.created_at > now() - interval '35 minutes')
         and (public.couture_edition(p_sku) ->> 'soldOut')::boolean then
        raise exception 'sold_out' using errcode = '22023';
      end if;
    end if;
  end if;
  -- The player's older open checkouts for this product (or any chat plan) are replaced; the server expires them in Stripe (Steam orders are never finalized).
  with old as (
    update public.purchases u set status = 'expired', updated_at = now()
     where u.player_id = uid and u.status = 'pending' and u.stripe_session_id <> p_session
       and (u.sku = p_sku or (prod.product_type = 'chat_pass'
                              and exists (select 1 from public.store_products o where o.sku = u.sku and o.product_type = 'chat_pass')))
    returning u.stripe_session_id)
  select coalesce(array_agg(stripe_session_id), '{}') into replaced from old;
  insert into public.purchases (stripe_session_id, player_id, sku) values (p_session, uid, p_sku)
  on conflict (stripe_session_id) do nothing;
  return replaced;
end;
$$;
revoke all on function public.start_purchase(text, text) from public, anon;
grant execute on function public.start_purchase(text, text) to authenticated;

revoke all on function public.season_settings() from public, anon, authenticated;
revoke all on function public.season_xp_note() from public, anon, authenticated;
revoke all on function public.season_give(uuid, jsonb, text, boolean) from public, anon, authenticated;
revoke all on function public.entitlements_season_items() from public, anon, authenticated;
revoke all on function public.season_state() from public, anon;
revoke all on function public.season_claim_all() from public, anon;
revoke all on function public.starter_pack_state() from public, anon;
grant execute on function public.season_state() to authenticated;
grant execute on function public.season_claim_all() to authenticated;
grant execute on function public.starter_pack_state() to authenticated;
